const specialistExamplesHeadings = {
  'ai-seo': 'AI-assisted SEO research, briefs, and content improvements.',
  'ai-social-media-marketing': 'AI-assisted social content shaped by human editorial direction.',
  'ai-ugc-ai-video-production': 'AI-assisted video concepts produced for specific marketing uses.',
  'ai-web-design-conversion': 'Website and landing-page concepts developed for clearer conversion paths.',
  'ai-content-marketing': 'Articles and content assets developed from approved briefs and sources.',
  'compliance-aware-ai-workflows': 'Review workflows designed around your approval requirements.',
};

function processForPage(page, family) {
  if (page.process) return page.process;
  if (!page.industry) return family.process;
  const input = industryInputs[page.industry];
  if (page.family === 'websites') return family.process.map((step, index) => index === 1 ? [step[0], `We create the agreed copy and visual direction. You provide ${input.website}, confirm accuracy, and share feedback.`] : step);
  if (page.family === 'seo') return family.process.map((step, index) => index === 1 ? [step[0], `We propose the pages, topics, and improvements to focus on. You confirm the ${input.seo}.`] : index === 2 ? [step[0], 'We complete the improvements included in the scope. You confirm specialist information and approve content before publication.'] : step);
  if (page.family === 'social') return family.process.map((step, index) => index === 1 ? [step[0], `We develop the agreed posts, visuals, or scripts using ${input.social}.`] : step);
  if (page.family === 'automation') return family.process.map((step, index) => index === 0 ? [step[0], `We review your ${input.automation}, the tools and handoffs involved, then identify what could be automated and where human review is needed.`] : step);
  if (page.family === 'ppc') return family.process.map((step, index) => index === 0 ? [step[0], `We discuss your ${input.ppc}, then propose the campaign approach, scope, advertising budget, and measurement plan for your approval.`] : step);
  if (page.family === 'branding') return family.process.map((step, index) => index === 0 ? [step[0], `We discuss your ${input.branding}, then recommend the themes and messages that will guide your personal brand.`] : step);
  return family.process;
}

function describeOffering(copy) {
  if (/^(We|You)\b/.test(copy)) return copy;
  return `We ${copy.charAt(0).toLowerCase()}${copy.slice(1)}`;
}

const familySlugs = Object.entries(pages).reduce((groups, [slug, page]) => {
  (groups[page.family] ||= []).push(slug);
  return groups;
}, {});

export const childServiceSlugs = Object.keys(pages);

export function getChildServiceData(slug) {
  const page = pages[slug];
  if (!page) return null;
  const family = familyInfo[page.family];
  const siblingLinks = familySlugs[page.family]
    .filter((item) => item !== slug)
    .slice(0, 2)
    .map((item) => [pages[item].title, `/services/${item}/`]);
  const related = page.related || [family.parent, ...siblingLinks];
  if (!page.related) {
    if (page.industry) related.push(industryLinks[page.industry]);
    if (page.portfolio) related.push(page.portfolio);
    related.push(['All services', '/services/'], ['Complete service directory', '/services/directory/']);
  }
  return {
    ...page,
    slug,
    card: page.card || family.card,
    included: page.included || (page.family === 'ai' ? page.focus : [...family.included, ...page.focus]),
    examples: page.examples.map(([title, copy]) => [title, page.preserveExampleCopy ? copy : describeOffering(copy)]),
    examplesEyebrow: page.examplesEyebrow || 'What we can create',
    examplesHeading: page.examplesHeading || specialistExamplesHeadings[slug] || family.examplesHeading,
    process: processForPage(page, family),
    processEyebrow: page.processEyebrow || 'How we work',
    processHeading: page.processHeading || family.processHeading,
    faq: page.faqItems || [page.faq, ...family.faq],
    cta: page.cta || family.cta,
    primary: page.primary || ['Discuss your project', '/contact/#contact-enquiry'],
    secondary: page.secondary || [`View ${family.parent[0]}`, family.parent[1]],
    related,
    showAudience: page.family === 'ai',
  };
}
